const staticData = $getWorkflowStaticData("global");

// Buscamos quién mandó el mensaje usando .first() para evitar errores
const telegramData = $('Telegram Trigger').first().json.message; 
const chatId = telegramData.chat.id;

// Tomamos el texto que la IA acaba de transcribir de forma segura
const textoTranscrito = "[Nota de voz transcrita]: " + $input.first().json.text; 

if (!staticData[chatId]) {
    staticData[chatId] = { mensajes: [], imagenes: [], ultimaHora: 0 };
}

// Lo guardamos en la memoria secreta
staticData[chatId].mensajes.push(textoTranscrito);
const horaActual = new Date().getTime();
staticData[chatId].ultimaHora = horaActual;

return {
    chatId: chatId,
    miHora: horaActual
};

const staticData = $getWorkflowStaticData("global");

// 1. Chat ID seguro
let chatId;
try {
  chatId = $('Telegram Trigger').first().json.message.chat.id;
} catch (e) {
  chatId = $json.message?.chat?.id || $('Telegram Trigger').first().json.chat?.id;
}

// 2. Extraemos el JSON de la nueva estructura de Gemini 2.5
let geminiRaw = "";
try {
  // Buscamos en la ruta específica de Gemini
  geminiRaw = $json.content.parts[0].text;
} catch (e) {
  // Por si n8n lo envuelve en un array extra
  geminiRaw = $json[0].content.parts[0].text;
}

// Limpiamos cualquier rastro de markdown por si acaso y lo convertimos a Objeto
geminiRaw = geminiRaw.replace(/```json/g, "").replace(/```/g, "").trim();
const visionData = JSON.parse(geminiRaw);

// 3. Texto original del vendedor (si mandó un mensajito junto con la foto)
let textoVendedor = "";
try {
  textoVendedor = $('Telegram Trigger').first().json.message.caption || "";
} catch(e) {}

// 4. Armamos la frase perfecta para el Agente Principal
let mensajeParaAgente = "";

if (visionData.tipo === "maquina") {
    mensajeParaAgente = `[FOTO DE MÁQUINA RECIBIDA] Texto del vendedor: "${textoVendedor}". Datos extraídos: ${visionData.datos_maquina}. URL de la foto: ${visionData.foto_url}`;
} 
else if (visionData.tipo === "pieza") {
    mensajeParaAgente = `[FOTO DE PIEZA RECIBIDA] Texto del vendedor: "${textoVendedor}". Pieza detectada: ${visionData.descripcion_pieza}. URL de la foto: ${visionData.foto_url}`;
} 
else {
    mensajeParaAgente = `[FOTO NO IDENTIFICADA] Texto del vendedor: "${textoVendedor}". URL de la foto: ${visionData.foto_url}`;
}

// 5. Guardamos en la memoria temporal
if (!staticData[chatId]) {
  staticData[chatId] = { mensajes: [], imagenes: [], ultimaHora: 0 };
}

staticData[chatId].mensajes.push(mensajeParaAgente);
const horaActual = new Date().getTime();
staticData[chatId].ultimaHora = horaActual;

return [{
  json: { chatId: chatId, miHora: horaActual }
}];

const staticData = $getWorkflowStaticData("global");
const chatId = $json.message.chat.id;
const text = $json.message.text || "";

// Ahora inicializamos también un espacio para "imagenes"
if (!staticData[chatId]) {
    staticData[chatId] = { mensajes: [], imagenes: [], ultimaHora: 0 };
}

staticData[chatId].mensajes.push(text);
const horaActual = new Date().getTime();
staticData[chatId].ultimaHora = horaActual;

return {
    chatId: chatId,
    miHora: horaActual
};

const staticData = $getWorkflowStaticData("global");
const chatId = $json.chatId;
const miHora = $json.miHora;

// 1. Validación de seguridad vital: Evita el error "undefined"
if (!staticData[chatId]) {
    return []; 
}

const datosActuales = staticData[chatId];

// 2. Control de tiempo: Si entró un mensaje más nuevo, este hilo se apaga
if (datosActuales.ultimaHora !== miHora) {
    return []; 
}

// 3. Empaquetamos todo el texto (ahora las descripciones de fotos vienen aquí)
const textoFinal = datosActuales.mensajes.join("\n\n");

// 4. Limpiamos la memoria para que el próximo pedido empiece en blanco
delete staticData[chatId]; 

// 5. Retornamos el paquete al Agente Principal (sin binarios, solo texto)
return [{
    json: {
        chatId: chatId,
        mensajeUnido: textoFinal
    }
}];

// Iteramos sobre la respuesta actual (los datos que devolvió Google Drive)
for (const item of $input.all()) {

    try {
        // Vamos al nodo donde REALMENTE entró la foto: el Trigger de Telegram
        const imagenOriginal = $('Telegram Trigger').first().binary;

        // Si la imagen existe, se la volvemos a pegar al paquete actual
        if (imagenOriginal) {
            item.binary = imagenOriginal;
        }
    } catch(e) {
        // Si hay algún problema, no colapsamos, seguimos adelante silenciosamente
    }
}

// Pasamos el paquete completo (JSON de Drive + Binario rescatado) a Gemini
return $input.all();
